component_creation_template.template:
// Always include proper file structure for new components:

// 1. Imports (React, utilities, types)
import React from 'react';
import { cn } from '@/lib/utils';

// 2. Type definitions
interface ComponentProps {
  // Define props with proper types
}

// 3. Component implementation with forwardRef for proper accessibility
const Component = React.forwardRef<HTMLElement, ComponentProps>(
  ({ className, ...props }, ref) => {
    return (
      <element
        ref={ref}
        className={cn("base-styles", className)}
        {...props}
      />
    );
  }
);

// 4. Display name for debugging
Component.displayName = "Component";

// 5. Export
export { Component };
